import io

def read_records(text):
    if text is None or (isinstance(text, str) and text.strip() == ""):
        # Could still be a comma-only blank? text.strip()=="," not empty,
        # so only fast-path truly empty/whitespace-only without commas.
        # Fall through for comma-containing text; general loop handles it.
        if text is None or "," not in text:
            return []
    reader = csv.reader(io.StringIO(text))
    headers = None
    rows = []
    for row in reader:
        if len(row) == 0 or (len(row) == 1 and row[0].strip() == ""):
            continue
        if headers is None:
            headers = row
            if len(set(headers)) != len(headers):
                raise ValueError("duplicate headers")
        else:
            if len(row) != len(headers):
                raise ValueError("field count mismatch")
            rows.append(dict(zip(headers, row)))
    if headers is None:
        return []
    return rows

def column_values(records, name):
    return [row[name] for row in records]
