{"files": {"core.py": "import heapq

def build_order(graph):
    deps = {}
    all_nodes = set(graph)
    for job, prerequisites in graph.items():
        s = set(prerequisites)
        deps[job] = s
        all_nodes.update(s)
    for node in all_nodes:
        if node not in deps:
            deps[node] = set()
    dependents = {node: set() for node in all_nodes}
    indegree = {}
    for node in all_nodes:
        indegree[node] = len(deps[node])
        for d in deps[node]:
            dependents[d].add(node)
    heap = sorted([n for n in all_nodes if indegree[n] == 0])
    heapq.heapify(heap)
    result = []
    while heap:
        job = heapq.heappop(heap)
        result.append(job)
        for dependent in dependents[job]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(heap, dependent)
    if len(result) != len(all_nodes):
        raise ValueError("cycle detected")
    return result

def job_count(graph):
    return len(set(graph).union(*(set(v) for v in graph.values())))
