{"files": {"core.py": "import csv
import io

def read_records(text):
    if text is None or text.strip() == "":
        return []
    reader = csv.reader(io.StringIO(text))
    records = list(reader)
    # Skip blank records: [] or single whitespace-only field
    def is_blank(row):
        if len(row) == 0:
            return True
        if len(row) == 1 and row[0].strip() == "":
            return True
        return False
    idx = 0
    while idx < len(records) and is_blank(records[idx]):
        idx += 1
    if idx >= len(records):
        return []
    headers = records[idx]
    if len(set(headers)) != len(headers):
        raise ValueError("duplicate headers")
    idx += 1
    result = []
    for row in records[idx:]:
        if is_blank(row):
            continue
        if len(row) != len(headers):
            raise ValueError(f"expected {len(headers)} fields, got {len(row)}")
        result.append(dict(zip(headers, row)))
    return result

def column_values(records, name):
    return [row[name] for row in records]
