{"files": {"core.py": "def _to_celsius(value, unit):
    if unit == 'C':
        return value
    if unit == 'F':
        return (value - 32) * 5 / 9
    return value - 273.15

def _from_celsius(value, unit):
    if unit == 'C':
        return value
    if unit == 'F':
        return value * 9 / 5 + 32
    return value + 273.15

def convert(value, source, target):
    try:
        s = source.strip().upper()
        t = target.strip().upper()
    except (AttributeError, TypeError):
        raise ValueError('unsupported conversion')
    if s not in ('C', 'F', 'K') or t not in ('C', 'F', 'K'):
        raise ValueError('unsupported conversion')
    if s == t:
        return value
    return _from_celsius(_to_celsius(value, s), t)

def c_to_f(value):
    return convert(value, 'C', 'F')

def f_to_c(value):
    return convert(value, 'F', 'C')

def temperature_label(value, unit):
    return f'{value:.1f} °{unit}'
