    TRANSITIONS = {
        'new': {'start': 'running', 'cancel': 'cancelled'},
        'running': {'finish': 'done', 'cancel': 'cancelled', 'pause': 'paused'},
        'paused': {'resume': 'running', 'cancel': 'cancelled'},
        'done': {},
        'cancelled': {},
    }
    def __init__(self):
        self.state = 'new'
        self.history = []
    def send(self, event):
        old = self.state
        try:
            new = self.TRANSITIONS[old][event]
        except KeyError:
            raise ValueError('invalid event')
        self.state = new
        self.history.append((old, event, new))
    def is_terminal(self):
        return self.state in ('done', 'cancelled')
