{"files": {"core.py": "def resolve_config(values):
    parsed = {}
    for k, v in values.items():
        s = v
        tokens = []
        buf = []
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch == '$':
                if i + 1 < n and s[i + 1] == '$':
                    buf.append('$')
                    i += 2
                elif i + 1 < n and s[i + 1] == '{':
                    j = s.find('}', i + 2)
                    if j == -1:
                        raise ValueError(f"unclosed reference in {k!r}")
                    name = s[i + 2:j]
                    if buf:
                        tokens.append(('lit', ''.join(buf)))
                        buf = []
                    tokens.append(('ref', name))
                    i = j + 1
                else:
                    buf.append('$')
                    i += 1
            else:
                buf.append(ch)
                i += 1
        if buf:
            tokens.append(('lit', ''.join(buf)))
        parsed[k] = tokens
    resolved = {}
    visiting = set()
    def dfs(key):
        if key in resolved:
            return resolved[key]
        if key in visiting:
            raise ValueError(f"reference cycle at {key!r}")
        visiting.add(key)
        parts = []
        for typ, val in parsed[key]:
            if typ == 'lit':
                parts.append(val)
            else:
                if val not in parsed:
                    raise ValueError(f"unknown reference {val!r}")
                parts.append(dfs(val))
        visiting.remove(key)
        result = ''.join(parts)
        resolved[key] = result
        return result
    for k in values:
        dfs(k)
    return dict(resolved)

def display_config(values):
    return '\n'.join(f'{key}={values[key]}' for key in sorted(values))
"}}

