{"files": {"core.py": "def resolve_config(values):
    resolved = {}
    visiting = set()

    def resolve_key(key):
        if key in resolved:
            return resolved[key]
        if key in visiting:
            raise ValueError(f"cycle detected at {key!r}")
        visiting.add(key)
        try:
            raw = values[key]
            parts = []
            i = 0
            n = len(raw)
            while i < n:
                c = raw[i]
                if c == '$':
                    if i + 1 < n and raw[i + 1] == '$':
                        parts.append('$')
                        i += 2
                    elif i + 1 < n and raw[i + 1] == '{':
                        j = raw.find('}', i + 2)
                        if j == -1:
                            raise ValueError(f"unclosed reference in {key!r}")
                        name = raw[i + 2:j]
                        if name not in values:
                            raise ValueError(f"unknown reference {name!r}")
                        parts.append(resolve_key(name))
                        i = j + 1
                    else:
                        parts.append('$')
                        i += 1
                else:
                    parts.append(c)
                    i += 1
            result = ''.join(parts)
            resolved[key] = result
            return result
        finally:
            visiting.discard(key)

    for k in list(values.keys()):
        resolve_key(k)
    return dict(resolved)

def display_config(values):
    return '\n'.join(f'{key}={values[key]}' for key in sorted(values))
