    def __init__(self, clock):
        self.clock, self.entries = clock, {}
    def put(self, key, value, ttl):
        if ttl <= 0:
            self.entries.pop(key, None)
            return
        self.entries[key] = (value, self.clock() + ttl)
    def get(self, key, default=None):
        if key not in self.entries:
