{"files": {"core.py": "import heapq

def build_order(graph):
    nodes = set(graph)
    deps = {}
    for job, prereqs in graph.items():
        s = set(prereqs)
        deps[job] = s
        nodes.update(s)
    for n in nodes:
        if n not in deps:
            deps[n] = set()
    indeg = {n: len(deps[n]) for n in nodes}
    dependents = {n: set() for n in nodes}
    for job, s in deps.items():
        for d in s:
            dependents[d].add(job)
    ready = [n for n in nodes if indeg[n] == 0]
    heapq.heapify(ready)
    result = []
    while ready:
        job = heapq.heappop(ready)
        result.append(job)
        for nxt in dependents[job]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                heapq.heappush(ready, nxt)
    if len(result) != len(nodes):
        raise ValueError("cycle detected")
    return result

def job_count(graph):
    return len(set(graph).union(*(set(v) for v in graph.values())))
