import io

def read_records(text):
    if text is None or text == "":
        return []
    reader = csv.reader(io.StringIO(text))
    headers = None
    records = []
    for row in reader:
        # Skip blank records: empty line yields [];
        # whitespace-only line without commas yields single whitespace field.
        if len(row) == 0:
            continue
        if len(row) == 1 and row[0].strip() == "":
            continue
        if headers is None:
            headers = row
            if len(set(headers)) != len(headers):
                raise ValueError("duplicate headers")
        else:
            if len(row) != len(headers):
                raise ValueError("field count mismatch")
            records.append(dict(zip(headers, row)))
    if headers is None:
        return []
    return records

def column_values(records, name):
    return [row[name] for row in records]
