    if not isinstance(unit, str):
        raise ValueError('unsupported conversion')
    normalized = unit.upper()
    if normalized not in ('C', 'F', 'K'):
        raise ValueError('unsupported conversion')
    return normalized

def convert(value, source, target):
    src = _normalize_unit(source)
    tgt = _normalize_unit(target)
    if src == tgt:
        return value
    if src == 'C':
        celsius = value
    elif src == 'F':
        celsius = (value - 32) * 5 / 9
    else:
        celsius = value - 273.15
    if tgt == 'C':
        return celsius
    if tgt == 'F':
        return celsius * 9 / 5 + 32
    return celsius + 273.15

def c_to_f(value):
    return convert(value, 'C', 'F')

def f_to_c(value):
    return convert(value, 'F', 'C')

def temperature_label(value, unit): return f'{value:.1f} °{unit}'
