            raise ValueError(f'invalid timeout: {value!r}')
    elif isinstance(value, (int, float)):
        num = float(value)
    else:
        raise ValueError(f'invalid timeout: {value!r}')
    if not math.isfinite(num) or num <= 0:
        raise ValueError(f'invalid timeout: {value!r}')
    return num

def load_settings(mapping):
    if mapping is None:
