    def __init__(self):
        self._buf = bytearray()

    def feed(self, chunk):
        if chunk:
            self._buf.extend(chunk)
        out = []
        while len(self._buf) >= 2:
            size = int.from_bytes(self._buf[:2], 'big')
            total = size + 3
            if len(self._buf) < total:
                break
            payload = bytes(self._buf[2:total - 1])
            checksum = self._buf[total - 1]
            if checksum != sum(payload) % 256:
