    def __init__(self):
        self._counts = {}
    def add(self, word):
        self._counts[word] = self._counts.get(word, 0) + 1
    def remove(self, word):
        if word not in self._counts:
            return False
        if self._counts[word] <= 1:
            del self._counts[word]
        else:
            self._counts[word] -= 1
        return True
