    nodes = set(graph)
    deps = {}
    for job, prereqs in graph.items():
        s = set(prereqs)
        deps[job] = s
        nodes.update(s)
    for n in nodes:
        if n not in deps:
            deps[n] = set()
    dependents = {n: set() for n in nodes}
    for job, s in deps.items():
        for p in s:
            dependents[p].add(job)
    indegree = {n: len(deps[n]) for n in nodes}
    import heapq
    heap = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(heap)
    result = []
    while heap:
        cur = heapq.heappop(heap)
        result.append(cur)
        for dep in dependents[cur]:
            indegree[dep] -= 1
            if indegree[dep] == 0:
                heapq.heappush(heap, dep)
    if len(result) != len(nodes):
        raise ValueError("cycle detected")
    return result
def job_count(graph):
    return len(set(graph).union(*(set(v) for v in graph.values())))
