    resolved = {}
    visiting = set()

    def expand_raw(s):
        parts = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == '$':
                if i + 1 < n and s[i + 1] == '$':
                    parts.append('$')
                    i += 2
                elif i + 1 < n and s[i + 1] == '{':
                    j = s.find('}', i + 2)
                    if j == -1:
                        raise ValueError(f'unclosed reference in {s!r}')
                    name = s[i + 2:j]
                    if name not in raw:
                        raise ValueError(f'unknown reference: {name!r}')
                    parts.append(('ref', name))
                    i = j + 1
                else:
                    parts.append('$')
                    i += 1
            else:
                parts.append(c)
                i += 1
        return parts

    def dfs(key):
        if key in resolved:
            return resolved[key]
        if key in visiting:
            raise ValueError(f'reference cycle at {key!r}')
        visiting.add(key)
        try:
            s = raw[key]
            tokens = expand_raw(s)
            out = []
            for t in tokens:
                if isinstance(t, tuple):
                    out.append(dfs(t[1]))
                else:
                    out.append(t)
            result = ''.join(out)
            resolved[key] = result
            return result
        finally:
            visiting.discard(key)

    for k in raw:
        dfs(k)
    return dict(resolved)

def display_config(values):
    return '\n'.join(f'{key}={values[key]}' for key in sorted(values))
