import json


def as_json(rows):
    return json.dumps(list(rows), sort_keys=True)


def as_text(rows, columns):
    return '\n'.join('\t'.join(str(row.get(c, '')) for c in columns) for row in rows)


def as_csv(rows, columns):
    cols = list(columns)
    buf = io.StringIO(newline='')
    writer = csv.writer(buf, lineterminator='\r\n')
    writer.writerow(cols)
    for row in rows:
        writer.writerow([row[c] if c in row and row[c] is not None else '' for c in cols])
    return buf.getvalue()


def render(rows, format, columns):
    data = list(rows)
    if format == 'json':
        return as_json(data)
    if format == 'text':
        return as_text(data, columns)
    if format == 'csv':
        return as_csv(data, columns)
    raise ValueError('unsupported format')
