import math

@dataclass
class Settings:
    timeout: float = 30.0
    retries: int = 3

def _parse_timeout(value):
    if isinstance(value, bool):
        raise ValueError(f'invalid timeout: {value!r}')
    if isinstance(value, str):
        s = value.strip()
        if not s:
            raise ValueError(f'invalid timeout: {value!r}')
        try:
            num = float(s)
        except ValueError:
            raise ValueError(f'invalid timeout: {value!r}')
    elif isinstance(value, int):
        num = float(value)
    elif isinstance(value, float):
        num = value
    else:
        raise ValueError(f'invalid timeout: {value!r}')
    if not math.isfinite(num) or num <= 0:
        raise ValueError(f'invalid timeout: {value!r}')
    return float(num)

def load_settings(mapping):
    if mapping is None:
        mapping = {}
    if 'timeout' not in mapping:
        return Settings()
    return Settings(timeout=_parse_timeout(mapping['timeout']))

def describe(settings):
    return f'timeout={settings.timeout:g}; retries={settings.retries}'
", "cli.py": "from settings import load_settings

def parse_cli(argv, defaults=None):
    if argv is None:
        argv = []
    base = dict(defaults) if defaults is not None else {}
    last = None
    seen = False
    i = 0
    n = len(argv)
    while i < n:
        arg = argv[i]
        if arg == '--timeout':
            if i + 1 >= n:
                raise ValueError('missing value for --timeout')
            last = argv[i + 1]
            seen = True
            i += 2
        else:
            raise ValueError(f'unknown argument: {arg!r}')
    if seen:
        base['timeout'] = last
    return load_settings(base)

def usage():
    return 'request [--timeout SECONDS]'
