class FrameReader:
    def __init__(self):
        self._buf = bytearray()

    def feed(self, chunk):
        if chunk:
            self._buf.extend(chunk)
        out = []
        while True:
            if len(self._buf) < 2:
                break
            size = int.from_bytes(self._buf[:2], 'big')
            total = size + 3
            if len(self._buf) < total:
                break
            frame = bytes(self._buf[:total])
            try:
                payload = decode(frame)
            except ValueError:
                self._buf.clear()
                raise
            out.append(payload)
            del self._buf[:total]
        return out

    def finish(self):
        if len(self._buf) != 0:
            raise ValueError('truncated tail')
        return None
